package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
import com.microsoft.playwright.*;
import com.microsoft.playwright.options.AriaRole;
import java.nio.file.Path;
final class ReportSchedulesBrowserAcceptance {
 static void run(BrowserTest h)throws Exception {
  var f=ReportSchedulesAcceptance.seed(h.store);String report=f.get("report").toString(),schedule="/reports/"+report+"/measurement-schedule";
  try(var p=Playwright.create();var browser=p.chromium().launch();var context=browser.newContext()){
   var page=context.newPage();h.login(page,"admin");page.navigate(h.base()+"/reports/"+report+"/measurements");page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Schedule measurement collection").setExact(true)).press("Enter");page.getByLabel("Collection interval in minutes").fill("5");page.getByLabel("Collection status").selectOption("true");ServiceOutagesBrowserAcceptance.click(page,"Save collection schedule");assertThat(page.locator("main")).containsText("enabled");ReleaseBrowserAcceptance.accessible(page);page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/report-schedule-light.png")).setFullPage(true));assertTrue(new WorkWorker(h.store).runOne(System.currentTimeMillis()+1000));page.reload();assertThat(page.locator("main")).containsText("succeeded");page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Inspect last collection job").setExact(true)).press("Enter");assertThat(page.locator("main")).containsText("report.capture");page.navigate(h.base()+"/admin/jobs");page.getByLabel("Work kind").selectOption("report.capture");ServiceOutagesBrowserAcceptance.click(page,"Find work");assertThat(page.locator("tbody")).containsText("report.capture");page.getByLabel("Work kind").selectOption("workflow.run");ServiceOutagesBrowserAcceptance.click(page,"Find work");assertThat(page.getByLabel("Work kind")).hasValue("workflow.run");page.navigate(h.base()+"/reports/"+report+"/measurements");assertThat(page.locator("tbody tr")).hasCount(1);ReportMeasurementsAcceptance.change(h.store,f.get("table").toString(),"30");ReportSchedulesAcceptance.due(h.store,report);assertTrue(new WorkWorker(h.store).runOne(System.currentTimeMillis()+1000));page.reload();assertThat(page.locator("tbody tr")).hasCount(2);ServiceOutagesBrowserAcceptance.click(page,"Dark mode");page.setViewportSize(390,844);ReleaseBrowserAcceptance.accessible(page);assertEquals(false,page.evaluate("document.documentElement.scrollWidth>window.innerWidth"));page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/scheduled-measurements-dark.png")).setFullPage(true));
   page.navigate(h.base()+schedule);page.getByLabel("Collection status").selectOption("false");ServiceOutagesBrowserAcceptance.click(page,"Save collection schedule");assertThat(page.locator("main")).containsText("paused");ReleaseBrowserAcceptance.accessible(page);assertEquals(false,page.evaluate("document.documentElement.scrollWidth>window.innerWidth"));assertEquals(false,page.evaluate("Array.from(document.querySelectorAll('main .panel')).some(p=>p.scrollWidth>p.clientWidth+1)"));page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/report-schedule-paused-dark.png")).setFullPage(true));assertFalse(new WorkWorker(h.store).runOne(System.currentTimeMillis()+1000));assertEquals(2,ReportSchedulesAcceptance.captures(h.store,report));page.locator("select[name=enabled]").evaluate("e=>{const o=document.createElement('option');o.value='invalid';o.text='Invalid';e.append(o);e.value='invalid';}");ServiceOutagesBrowserAcceptance.click(page,"Save collection schedule");assertThat(page.locator("main")).containsText("Choose collection status");
  }
 }
}
